<!-- ===== FEATURE STRIP ===== -->
<section style="background: #fff;">
  <div style="max-width: 1240px; margin: 0 auto; padding: 0 24px; transform: translateY(-44px);">
    <div style="display: grid; grid-template-columns: repeat(3, 1fr); gap: 22px;" class="gs-3col">
      <div style="background: #0d1826; color: #fff; border-radius: var(--gs-r-card, 16px); padding: 30px; display: flex; gap: 18px; align-items: flex-start;">
        <div style="width: 54px; height: 54px; border-radius: var(--gs-r-tile, 12px); background: color-mix(in srgb, var(--gs-accent, #2CA69C) 16%, transparent); color: var(--gs-accent-lite, #6FDED3); display: grid; place-items: center; flex-shrink: 0;"><svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><polyline points="16 8 20 12 16 16"/><polyline points="8 8 4 12 8 16"/></svg></div>
        <div><h3 style="font-family: 'Space Grotesk'; font-weight: 600; font-size: 19px; margin-bottom: 7px;"><x-t k="f1Title"/></h3><p style="font-size: 14.5px; color: #a3b0bd; line-height: 1.6;"><x-t k="f1Body"/></p></div>
      </div>
      <div style="background: var(--gs-accent, #2CA69C); color: #fff; border-radius: var(--gs-r-card, 16px); padding: 30px; display: flex; gap: 18px; align-items: flex-start;">
        <div style="width: 54px; height: 54px; border-radius: var(--gs-r-tile, 12px); background: rgba(255,255,255,.18); color: #fff; display: grid; place-items: center; flex-shrink: 0;"><svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><rect x="7" y="3" width="10" height="18" rx="2"/><path d="M11 18h2"/></svg></div>
        <div><h3 style="font-family: 'Space Grotesk'; font-weight: 600; font-size: 19px; margin-bottom: 7px;"><x-t k="f2Title"/></h3><p style="font-size: 14.5px; color: rgba(255,255,255,.85); line-height: 1.6;"><x-t k="f2Body"/></p></div>
      </div>
      <div style="background: #fff; border: 1px solid #e7edee; color: #0d1826; border-radius: var(--gs-r-card, 16px); padding: 30px; display: flex; gap: 18px; align-items: flex-start; box-shadow: 0 20px 40px rgba(13,24,38,.06);">
        <div style="width: 54px; height: 54px; border-radius: var(--gs-r-tile, 12px); background: #eefaf8; color: #17877e; display: grid; place-items: center; flex-shrink: 0;"><svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="3.2"/><path d="M12 3v2M12 19v2M3 12h2M19 12h2M5.6 5.6l1.4 1.4M17 17l1.4 1.4M18.4 5.6L17 7M7 17l-1.4 1.4"/></svg></div>
        <div><h3 style="font-family: 'Space Grotesk'; font-weight: 600; font-size: 19px; margin-bottom: 7px;"><x-t k="mgmtSystems"/></h3><p style="font-size: 14.5px; color: #6a7a8a; line-height: 1.6;"><x-t k="f3Body"/></p></div>
      </div>
    </div>
  </div>
</section>
